5.7 Extracting Selected Nested Detail Fields
The details object contains different fields for different event types.
Rather than flattening every nested field, the analysis extracts selected variables that are useful for later incident reconstruction:

detail_task;
detail_action;
detail_target_agent;
detail_target;
detail_file;
detail_content_source;
detail_path;
virus_flag.



Show the code
events_enriched &lt;- events_clean %&gt;%
  mutate(
    detail_task = map_chr(
      details,
      ~ pluck_chr(
        .x,
        "task"
      )
    ),
    detail_action = map_chr(
      details,
      ~ pluck_chr(
        .x,
        "action"
      )
    ),
    detail_target_agent = map_chr(
      details,
      ~ pluck_chr(
        .x,
        "target_agent"
      )
    ),
    detail_target = map_chr(
      details,
      ~ pluck_chr(
        .x,
        "target"
      )
    ),
    detail_file = map_chr(
      details,
      ~ pluck_chr(
        .x,
        "file"
      )
    ),
    detail_content_source = map_chr(
      details,
      ~ pluck_chr(
        .x,
        "content_source"
      )
    ),
    nested_path = map_chr(
      details,
      ~ pluck_chr(
        .x,
        "args",
        "path"
      )
    ),
    direct_path = map_chr(
      details,
      ~ pluck_chr(
        .x,
        "path"
      )
    ),
    file_path = map_chr(
      seq_along(
        details
      ),
      ~ first_non_missing_chr(
        nested_path[[.x]],
        direct_path[[.x]],
        detail_file[[.x]],
        detail_content_source[[.x]]
      )
    ),
    virus_flag = map_lgl(
      details,
      ~ pluck_lgl(
        .x,
        "virus"
      ) |
        identical(
          pluck_chr(
            .x,
            "task"
          ),
          "virus"
        )
    )
  )

6.2 Creating the Agent Extraction Function
Each suspicious handoff event contains a list of parties. The following function extracts personal-agent identifiers from each event.
The actor-normalisation function created earlier is reused so that inconsistent capitalisation or prefix formats do not create duplicated network nodes.


Show the code
extract_agent_parties &lt;- function(x) {
  agent_values &lt;- as.character(
    x
  ) %&gt;%
    keep(
      ~ str_detect(
        .x,
        regex(
          "^agent[:/]person:",
          ignore_case = TRUE
        )
      )
    ) %&gt;%
    normalise_actor()

  unique(
    agent_values
  )
}

