5.6 Creating the boxbreaks function


Code
boxbreaks &lt;- function(v, mult = 1.5) {

  qv &lt;- unname(quantile(v, na.rm = TRUE))
  iqr &lt;- qv[4] - qv[2]
  upfence &lt;- qv[4] + mult * iqr
  lofence &lt;- qv[2] - mult * iqr

  bb &lt;- vector(mode = "numeric", length = 7)

  if (lofence &lt; qv[1]) {
    bb[1] &lt;- lofence
    bb[2] &lt;- floor(qv[1])
  } else {
    bb[2] &lt;- lofence
    bb[1] &lt;- qv[1]
  }

  if (upfence &gt; qv[5]) {
    bb[7] &lt;- upfence
    bb[6] &lt;- ceiling(qv[5])
  } else {
    bb[6] &lt;- upfence
    bb[7] &lt;- qv[5]
  }

  bb[3:5] &lt;- qv[2:4]

  return(bb)
}




